from collections import OrderedDict


class NamespaceLRU:
    """单个 namespace 一份 access-order LRU。"""

    def __init__(self, size: int = 3):
        self.size = size
        self.data: OrderedDict = OrderedDict()

    def get(self, key):
        if key not in self.data:
            return None
        self.data.move_to_end(key)
        return self.data[key]

    def put(self, key, value):
        self.data[key] = value
        self.data.move_to_end(key)
        while len(self.data) > self.size:
            self.data.popitem(last=False)

    def clear(self):
        self.data.clear()


class CacheManager:
    """模拟 MyBatis 二级缓存 + TransactionalCache 的提交可见性。"""

    def __init__(self, size=3):
        self.size = size
        self.caches = {}                 # namespace -> NamespaceLRU
        self.staging = {}                # (namespace, key) -> value，提交前不可见
        self.db_queries = 0

    def cache_of(self, ns):
        return self.caches.setdefault(ns, NamespaceLRU(self.size))

    def select(self, ns, key):
        hit = self.cache_of(ns).get(key)
        if hit is not None:
            return hit, "l2hit"
        self.db_queries += 1
        value = "row-%s-%s" % (ns, key)
        self.staging[(ns, key)] = value  # 先暂存，commit 后才入缓存
        return value, "db"

    def commit(self):
        for (ns, key), value in self.staging.items():
            self.cache_of(ns).put(key, value)
        self.staging.clear()

    def update(self, ns):
        # 关键：只清本 namespace（这是脏读的来源）
        self.cache_of(ns).clear()
        for k in [k for k in self.staging if k[0] == ns]:
            del self.staging[k]


if __name__ == "__main__":
    cm = CacheManager(size=3)
    v1, src1 = cm.select("UserMapper", 1)
    print("s1 select", v1, src1)
    _, src2 = cm.select("UserMapper", 1)
    print("before commit", src2)      # 尚未 commit，仍会查库
    cm.commit()
    _, src3 = cm.select("UserMapper", 1)
    print("after commit", src3)       # l2hit
    for k in (2, 3, 4):
        cm.select("UserMapper", k)
        cm.commit()
    print("lru keys", list(cm.caches["UserMapper"].data.keys()))
    cm.select("OrderMapper", 1)
    cm.commit()
    cm.update("OrderMapper")          # 只清 OrderMapper
    _, src4 = cm.select("UserMapper", 2)   # key=2 仍在 UserMapper 缓存中
    print("UserMapper after OrderMapper update", src4)
    print("db queries", cm.db_queries)
